// scripts/fetch-asset.js
const fs = require("fs");
const https = require("https");
const crypto = require("crypto");

const url = "https://example.com/assets/tool.txt";
const out = "./downloaded-tool.txt";
const expectedSha256 = "REPLACE_WITH_REAL_HASH";

https.get(url, res => {
  if (res.statusCode !== 200) {
    console.error("Download failed:", res.statusCode);
    process.exit(1);
  }
  const file = fs.createWriteStream(out);
  const hash = crypto.createHash("sha256");
  res.on("data", chunk => hash.update(chunk));
  res.pipe(file);
  file.on("finish", () => {
    file.close(() => {
      const got = hash.digest("hex");
      if (got !== expectedSha256) {
        fs.unlinkSync(out);
        console.error("Checksum mismatch");
        process.exit(1);
      }
      console.log("Asset downloaded and verified:", out);
      console.log("Not executing automatically.");
    });
  });
});
```

