## `bin/cli.js`

This version is safe: it only scans the current project’s dependency metadata and only sends results if explicitly enabled.

```js
#!/usr/bin/env node
import minimist from 'minimist';
import { scanProjectLicenses } from '../lib/scan.js';
import { evaluatePolicy } from '../lib/policy.js';
import { sendReport } from '../lib/api.js';

const args = minimist(process.argv.slice(2));
const isPostinstall = !!args.postinstall;

async function main() {
  const enabled = process.env.LICENSE_CHECK_ENABLE === 'true';
  const apiUrl = process.env.LICENSE_CHECK_API_URL;
  const apiToken = process.env.LICENSE_CHECK_API_TOKEN;

  if (isPostinstall && !enabled) {
    console.log('[license-check] Skipping postinstall scan; set LICENSE_CHECK_ENABLE=true to enable.');
    return;
  }

  const report = await scanProjectLicenses(process.cwd());

  const policy = {
    allow: ['MIT', 'Apache-2.0', 'BSD-2-Clause', 'BSD-3-Clause', 'ISC'],
    deny: ['GPL-3.0', 'AGPL-3.0']
  };

  const result = evaluatePolicy(report, policy);

  console.log('[license-check] Dependencies scanned:', report.dependencies.length);
  console.log('[license-check] Violations:', result.violations.length);

  if (enabled && apiUrl && apiToken) {
    await sendReport(apiUrl, apiToken, {
      project: process.env.npm_package_name || 'unknown-project',
      version: process.env.npm_package_version || '0.0.0',
      report,
      result
    });
    console.log('[license-check] Report sent.');
  } else {
    console.log('[license-check] No API upload configured.');
  }

  if (result.violations.length > 0) {
    process.exitCode = 1;
  }
}

main().catch(err => {
  console.error('[license-check] Error:', err.message);
  process.exit(1);
});
```

## `lib/scan.js`

```js
import fs from 'fs/promises';
import path from 'path';

async function readJson(file) {
  const content = await fs.readFile(file, 'utf8');
  return JSON.parse(content);
}

async function exists(file) {
  try {
    await fs.access(file);
    return true;
  } catch {
    return false;
  }
}

async function collectPackages(nodeModulesDir, results = []) {
  if (!(await exists(nodeModulesDir))) return results;

  const entries = await fs.readdir(nodeModulesDir, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;

    if (entry.name.startsWith('@')) {
      await collectPackages(path.join(nodeModulesDir, entry.name), results);
      continue;
    }

    const pkgDir = path.join(nodeModulesDir, entry.name);
    const pkgJsonPath = path.join(pkgDir, 'package.json');

    if (await exists(pkgJsonPath)) {
      try {
        const pkg = await readJson(pkgJsonPath);
        results.push({
          name: pkg.name,
          version: pkg.version,
          license: pkg.license || null,
          repository:
            typeof pkg.repository === 'string'
              ? pkg.repository
              : pkg.repository?.url || null
        });
      } catch {
        // ignore malformed package
      }
    }
  }

  return results;
}

export async function scanProjectLicenses(projectDir) {
  const projectPkgPath = path.join(projectDir, 'package.json');
  const projectPkg = (await exists(projectPkgPath)) ? await readJson(projectPkgPath) : {};

  const dependencies = await collectPackages(path.join(projectDir, 'node_modules'));

  return {
    project: {
      name: projectPkg.name || path.basename(projectDir),
      version: projectPkg.version || null
    },
    dependencies
  };
}
```

## `lib/policy.js`

```js
export function evaluatePolicy(report, policy) {
  const violations = [];

  for (const dep of report.dependencies) {
    const license = dep.license || 'UNKNOWN';

    if (policy.deny.includes(license)) {
      violations.push({
        name: dep.name,
        version: dep.version,
        license,
        reason: 'Denied license'
      });
      continue;
    }

    if (policy.allow.length > 0 && !policy.allow.includes(license)) {
      violations.push({
        name: dep.name,
        version: dep.version,
        license,
        reason: 'License not in allow list'
      });
    }
  }

  return { violations };
}
```

## `lib/api.js`

```js
export async function sendReport(apiUrl, apiToken, body) {
  const res = await fetch(apiUrl, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'authorization': `Bearer ${apiToken}`
    },
    body: JSON.stringify(body)
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`API error ${res.status}: ${text}`);
  }
}
```

